#include "stdlib/math/base/special/gamma_lanczos_sumf.h"

// BEGIN: rational_pq

/**
* Evaluates a rational function (i.e., the ratio of two polynomials described by the coefficients stored in \\(P\\) and \\(Q\\)).
*
* ## Notes
*
* -   Coefficients should be sorted in ascending degree.
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the rational function
* @return     evaluated rational function
*/
static float rational_pq( const float x ) {
	float ax;
	float ix;
	float s1;
	float s2;
	if ( x == 0.0 ) {
		return 1.0 / 0.0;
	}
	if ( x < 0.0 ) {
		ax = -x;
	} else {
		ax = x;
	}
	if ( ax <= 1.0 ) {
		s1 = 58.52061462402344 + (x * (182.52490234375 + (x * (211.09710693359375 + (x * (112.25265502929688 + (x * (27.519201278686523 + (x * 2.5066285133361816)))))))));
		s2 = 0.0 + (x * (24.0 + (x * (50.0 + (x * (35.0 + (x * (10.0 + (x * 1.0)))))))));
	} else {
		ix = 1.0 / x;
		s1 = 2.5066285133361816 + (ix * (27.519201278686523 + (ix * (112.25265502929688 + (ix * (211.09710693359375 + (ix * (182.52490234375 + (ix * 58.52061462402344)))))))));
		s2 = 1.0 + (ix * (10.0 + (ix * (35.0 + (ix * (50.0 + (ix * (24.0 + (ix * 0.0)))))))));
	}
	return s1 / s2;
}

// END: rational_pq

/**
* Calculates the Lanczos sum for the approximation of the gamma function for single-precision floating-point number.
*
* @param x    input value
* @return     Lanczos sum approximation
*
* @example
* float v = stdlib_base_gammaLanczosSum( 4.0f );
* // returns ~950.366f
*/
float stdlib_base_gamma_lanczos_sumf( const float x ) {
	return rational_pq( x );
}
